import type { ConsultationRead } from "./contracts";
import { cashFlowObject as object, cashFlowText as text, cashFlowUuid as uuid } from "../portfolio/cashFlowApiContract";
import { TICKET_BODY_LIMIT, validateTicketHistoryAccess, validateTicketRequest, type TicketCommand, type TicketRequest } from "./tickets";
import { validateTicketIntent, type TicketIntent } from "./ticketIntent";
import { ticketStorageParent } from "./ticketStorageContracts";
import type { TicketStorageAttempt } from "./ticketStorageRequest";

export const TICKET_ATTEMPT_ENDPOINT = "/api/consultation/ticket-attempts";
export const TICKET_ATTEMPT_LIST_LIMIT = 500; // Serialization bound, not a service quota.
export type TicketAttemptSelection = { relationshipId: string } & (
  | { mode: "list" }
  | { mode: "lookup"; preparationId: string; clientToken?: never }
  | { mode: "lookup"; clientToken: string; preparationId?: never }
);
export interface TicketAttemptMetadata { preparationId: string; requestId: string; kind: TicketCommand["kind"]; baseVersion: number; bodyHash: string; createdAt: string }
export interface TicketPreparationReceipt { contractVersion: "consultation-ticket-preparation.v1"; actorId: string; relationshipId: string; preparationId: string; requestId: string; clientToken: string; bodyHash: string; createdAt: string; fixtureRunId: string; reused: boolean }
export interface TicketPrepared extends Omit<TicketPreparationReceipt, "contractVersion" | "reused"> { contractVersion: "consultation-ticket-prepared.v1"; body: string }
export interface TicketAttemptList { contractVersion: "consultation-ticket-attempt-list.v1"; actorId: string; relationshipId: string; attempts: TicketAttemptMetadata[] }
export interface TicketAttemptLookup { contractVersion: "consultation-ticket-attempt-lookup.v1"; actorId: string; relationshipId: string; preparationId: string | null; clientToken: string | null; state: "found" | "confirmed_absent"; prepared: TicketPrepared | null }
export type TicketAttemptRead = TicketAttemptList | TicketAttemptLookup;
const id = (value: unknown) => { if (!uuid(value)) throw Error("شناسهٔ تلاش معتبر نیست."); return value.toLowerCase(); };
const hash = (value: unknown) => { if (typeof value !== "string" || !/^[a-f0-9]{64}$/.test(value)) throw Error("هش تلاش معتبر نیست."); return value; };
const kinds: TicketCommand["kind"][] = ["open", "member_followup", "advisor_clarification", "link_recommendation", "close"];
function time(value: unknown) {
  if (typeof value !== "string" || !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,6})?(?:Z|[+-]\d\d:\d\d)$/.test(value) || !Number.isFinite(Date.parse(value))) throw Error("زمان DB تلاش معتبر نیست.");
  return value;
}
export function frozenTicketIntentBody(body: unknown): TicketIntent {
  if (typeof body !== "string" || !body || new TextEncoder().encode(body).length > TICKET_BODY_LIMIT) throw Error("متن اصلی تلاش معتبر نیست.");
  const input = validateTicketRequest(JSON.parse(body));
  return validateTicketIntent({ body, expectedActorId: input.expectedActorId, requestId: input.command.requestId, clientToken: input.clientToken, serviceRightState: "not_connected", writeEnabled: false, blockedReason: "service_entitlement_not_connected" });
}
export async function ticketBodyHash(body: string): Promise<string> {
  return Array.from(new Uint8Array(await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(body))), byte => byte.toString(16).padStart(2, "0")).join("");
}
export function parseTicketAttemptSelection(params: URLSearchParams): TicketAttemptSelection {
  const mode = params.get("mode"), byId = params.has("preparationId");
  const keys = mode === "list" ? ["mode", "relationshipId"] : mode === "lookup" ? ["mode", "relationshipId", byId ? "preparationId" : "clientToken"] : [];
  if (params.size !== keys.length || [...params.keys()].some(key => !keys.includes(key) || params.getAll(key).length !== 1)) throw Error("مسیر خواندن تلاش معتبر نیست.");
  const relationshipId = id(params.get("relationshipId"));
  if (mode === "list") return { mode, relationshipId };
  if (mode !== "lookup") throw Error("نوع خواندن تلاش معتبر نیست.");
  return byId ? { mode, relationshipId, preparationId: id(params.get("preparationId")) } : { mode, relationshipId, clientToken: text(params.get("clientToken"), 200) };
}
function commonReceipt(row: Record<string, unknown>, parent: ConsultationRead) {
  if (row.actorId !== parent.actor.id || row.relationshipId !== parent.selected!.id) throw Error("تلاش متعلق به همین هویت و رابطه نیست.");
  return { actorId: parent.actor.id, relationshipId: parent.selected!.id, preparationId: id(row.preparationId), requestId: id(row.requestId), clientToken: text(row.clientToken, 200), bodyHash: hash(row.bodyHash), createdAt: time(row.createdAt), fixtureRunId: text(row.fixtureRunId, 200) };
}
export async function validateTicketPreparationReceipt(value: unknown, source: ConsultationRead, body: string): Promise<TicketPreparationReceipt> {
  const intent = frozenTicketIntentBody(body), input = validateTicketRequest(JSON.parse(intent.body));
  const parent = ticketStorageParent(source, input.expectedActorId, input.command.relationshipId);
  const row = object(value, ["contractVersion", "actorId", "relationshipId", "preparationId", "requestId", "clientToken", "bodyHash", "createdAt", "fixtureRunId", "reused"]);
  if (row.contractVersion !== "consultation-ticket-preparation.v1" || typeof row.reused !== "boolean") throw Error("رسید حفظ تلاش معتبر نیست.");
  const receipt = commonReceipt(row, parent);
  if (receipt.requestId !== input.command.requestId || receipt.clientToken !== input.clientToken || receipt.bodyHash !== await ticketBodyHash(body)) throw Error("رسید حفظ با bytes اصلی مطابق نیست.");
  return { contractVersion: "consultation-ticket-preparation.v1", ...receipt, reused: row.reused };
}
export async function validateTicketAttemptRead(value: unknown, source: ConsultationRead, selection: TicketAttemptSelection): Promise<TicketAttemptRead> {
  // Access validation is outside callers' transient read-error fallback.
  const parent = ticketStorageParent(source, source.actor.id, selection.relationshipId);
  if (selection.mode === "list") {
    const row = object(value, ["contractVersion", "actorId", "relationshipId", "attempts"]);
    if (row.contractVersion !== "consultation-ticket-attempt-list.v1" || row.actorId !== parent.actor.id || row.relationshipId !== selection.relationshipId || !Array.isArray(row.attempts) || row.attempts.length > TICKET_ATTEMPT_LIST_LIMIT) throw Error("فهرست کامل تلاش‌ها معتبر نیست.");
    const attempts: TicketAttemptMetadata[] = row.attempts.map(value => {
      const item = object(value, ["preparationId", "requestId", "kind", "baseVersion", "bodyHash", "createdAt"]);
      if (!kinds.includes(item.kind as TicketCommand["kind"]) || !Number.isInteger(item.baseVersion) || (item.baseVersion as number) < 0 || (item.baseVersion as number) > 2147483646) throw Error("مبنای تلاش معتبر نیست.");
      return { preparationId: id(item.preparationId), requestId: id(item.requestId), kind: item.kind as TicketCommand["kind"], baseVersion: item.baseVersion as number, bodyHash: hash(item.bodyHash), createdAt: time(item.createdAt) };
    });
    if (new Set(attempts.map(item => item.preparationId)).size !== attempts.length) throw Error("تلاش تکراری در فهرست است.");
    return { contractVersion: "consultation-ticket-attempt-list.v1", actorId: parent.actor.id, relationshipId: selection.relationshipId, attempts };
  }
  const row = object(value, ["contractVersion", "actorId", "relationshipId", "preparationId", "clientToken", "state", "prepared"]);
  if (row.contractVersion !== "consultation-ticket-attempt-lookup.v1" || row.actorId !== parent.actor.id || row.relationshipId !== selection.relationshipId || row.preparationId !== (selection.preparationId ?? null) || row.clientToken !== (selection.clientToken ?? null)) throw Error("همبستگی جست‌وجوی تلاش تغییر کرده است.");
  const common = { contractVersion: "consultation-ticket-attempt-lookup.v1" as const, actorId: parent.actor.id, relationshipId: selection.relationshipId, preparationId: selection.preparationId ?? null, clientToken: selection.clientToken ?? null };
  if (row.state === "confirmed_absent" && row.prepared === null) return { ...common, state: row.state, prepared: null };
  if (row.state !== "found") throw Error("وضعیت نامعلوم، نبود تلاش نیست.");
  const saved = object(row.prepared, ["contractVersion", "actorId", "relationshipId", "preparationId", "requestId", "clientToken", "bodyHash", "createdAt", "fixtureRunId", "body"]);
  if (saved.contractVersion !== "consultation-ticket-prepared.v1") throw Error("نسخهٔ متن محفوظ معتبر نیست.");
  const metadata = commonReceipt(saved, parent), intent = frozenTicketIntentBody(saved.body), input = validateTicketRequest(JSON.parse(intent.body));
  validateTicketHistoryAccess(input, parent);
  if (metadata.requestId !== input.command.requestId || metadata.clientToken !== input.clientToken || (selection.preparationId && metadata.preparationId !== selection.preparationId) || (selection.clientToken && metadata.clientToken !== selection.clientToken) || metadata.bodyHash !== await ticketBodyHash(intent.body)) throw Error("متن/توکن/هش محفوظ مطابق نیست.");
  return { ...common, state: "found", prepared: { contractVersion: "consultation-ticket-prepared.v1", ...metadata, body: intent.body } };
}
export function restorePreparedTicketAttempt(value: TicketPrepared, parent: ConsultationRead): TicketStorageAttempt {
  const intent = frozenTicketIntentBody(value.body), input: TicketRequest = validateTicketRequest(JSON.parse(intent.body));
  validateTicketHistoryAccess(input, parent);
  if (value.actorId !== parent.actor.id || value.relationshipId !== input.command.relationshipId || value.requestId !== input.command.requestId || value.clientToken !== input.clientToken) throw Error("تلاش محفوظ متعلق به همین رابطه نیست.");
  // Original bytes are used verbatim; the frozen writeEnabled=false stays false.
  return Object.freeze({ intent, fixtureRunId: value.fixtureRunId });
}

import { buildCashFlow, type CashFlowCoverage, type CashFlowEntry, type CashFlowInput, type CashFlowPeriod, type CashFlowReport } from "./cashFlow";

type WithoutOwner<T> = T extends unknown ? Omit<T, "ownerId"> : never;
export interface CashFlowPayload {
  contractVersion: 1;
  period: CashFlowPeriod;
  accountDefinitions: { accountKey: string; label: string }[];
  scopeAccountKeys: string[];
  opening: CashFlowInput["opening"];
  coverage: Record<"planned" | "actual", CashFlowCoverage & { memberAffirmed: boolean }>;
  entries: WithoutOwner<CashFlowEntry>[];
}
export interface CashFlowWriteRequest {
  contractVersion: "cash-flow-request.v1"; expectedOwnerId: string; clientToken: string; baseVersion: number; payload: CashFlowPayload;
}
export interface CashFlowReceipt {
  contractVersion: "cash-flow-write.v1"; ownerId: string; versionId: string; version: number;
  entryCount: number; reused: boolean; canonicalContentHash: string;
}
export interface CashFlowRead {
  contractVersion: "cash-flow-read.v1"; state: "ready" | "empty"; ownerId: string; period: CashFlowPeriod;
  snapshot: null | { id: string; version: number; createdAt: string; payload: CashFlowPayload };
  report: CashFlowReport | null;
  latest: { state: "ready" | "error"; id: string | null; version: number | null };
  history: { state: "ready" | "error"; items: { id: string; version: number; createdAt: string }[]; nextBeforeVersion: number | null };
}
export type CashFlowErrorCode = "INVALID_INPUT" | "AUTH_REQUIRED" | "FORBIDDEN" | "OWNER_CHANGED" | "ORIGIN_FORBIDDEN" | "NOT_FOUND" | "CONFLICT" | "BODY_TOO_LARGE" | "RATE_LIMITED" | "AUTH_UNAVAILABLE" | "READ_UNAVAILABLE" | "WRITE_UNAVAILABLE";
export interface CashFlowApiError { state: "error"; code: CashFlowErrorCode; error: string }

export const CASH_FLOW_BODY_LIMIT = 1_000_000;
export function cashFlowObject(value: unknown, keys: readonly string[]): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error("Invalid cash-flow object");
  const result = value as Record<string, unknown>;
  if (Object.keys(result).length !== keys.length || keys.some(key => !Object.hasOwn(result, key))) throw new Error("Invalid cash-flow keys");
  return result;
}
export function cashFlowText(value: unknown, max: number): string {
  if (typeof value !== "string" || !value.trim() || [...value.trim()].length > max || value.includes("\0")) throw new Error("Invalid cash-flow text");
  return value.trim();
}
export function cashFlowUuid(value: unknown): value is string {
  return typeof value === "string" && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
}
export function cashFlowDay(value: unknown): string {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value) || value.startsWith("0000") || !Number.isFinite(Date.parse(value)) || new Date(value).toISOString().slice(0, 10) !== value) throw new Error("Invalid cash-flow day");
  return value;
}
export function validateCashFlowPeriod(value: unknown): CashFlowPeriod {
  const row = cashFlowObject(value, ["startOn", "endOn"]);
  const startOn = cashFlowDay(row.startOn), endOn = cashFlowDay(row.endOn);
  const days = (Date.parse(endOn) - Date.parse(startOn)) / 86_400_000;
  if (days < 0 || days > 365) throw new Error("Invalid cash-flow period");
  return { startOn, endOn };
}
function amount(value: unknown, signed = false): number | null {
  if (value === null) return null;
  if (typeof value !== "number" || !Number.isSafeInteger(value) || (!signed && value < 0)) throw new Error("Invalid cash-flow amount");
  return value;
}
function source(value: unknown): CashFlowCoverage["source"] {
  if (value === null) return null;
  const row = cashFlowObject(value, ["label", "observedOn"]), label = cashFlowText(row.label, 160);
  if (["unknown", "نامشخص", "-", "—"].includes(label.toLowerCase())) throw new Error("Unknown cash-flow source");
  return { label, observedOn: cashFlowDay(row.observedOn) };
}
const nullableText = (value: unknown, max: number): string | null => value === null || typeof value === "string" && !value.trim() ? null : cashFlowText(value, max);
/** Browser/server shape guard; SQL remains the authoritative ownership/transaction boundary. */
export function validateCashFlowPayload(value: unknown): CashFlowPayload {
  const row = cashFlowObject(value, ["contractVersion", "period", "accountDefinitions", "scopeAccountKeys", "opening", "coverage", "entries"]);
  if (row.contractVersion !== 1) throw new Error("Invalid cash-flow contract");
  const period = validateCashFlowPeriod(row.period);
  if (!Array.isArray(row.accountDefinitions) || row.accountDefinitions.length < 1 || row.accountDefinitions.length > 50) throw new Error("Invalid cash-flow accounts");
  const accountDefinitions = row.accountDefinitions.map(value => { const account = cashFlowObject(value, ["accountKey", "label"]); return { accountKey: cashFlowText(account.accountKey, 200), label: cashFlowText(account.label, 160) }; });
  const keys = new Set(accountDefinitions.map(account => account.accountKey));
  if (keys.size !== accountDefinitions.length || !Array.isArray(row.scopeAccountKeys) || row.scopeAccountKeys.length < 1 || row.scopeAccountKeys.length > 50) throw new Error("Invalid cash-flow scope");
  const scopeAccountKeys = row.scopeAccountKeys.map(value => cashFlowText(value, 200));
  if (new Set(scopeAccountKeys).size !== scopeAccountKeys.length || scopeAccountKeys.some(key => !keys.has(key))) throw new Error("Invalid cash-flow scope references");
  const coverageRow = cashFlowObject(row.coverage, ["planned", "actual"]);
  const lane = (basis: "planned" | "actual"): CashFlowPayload["coverage"]["planned"] => {
    const item = cashFlowObject(coverageRow[basis], ["status", "memberAffirmed", "source"]);
    if (item.status !== "unknown" && item.status !== "partial" && item.status !== "complete" || typeof item.memberAffirmed !== "boolean") throw new Error("Invalid cash-flow coverage");
    const provenance = source(item.source);
    if (item.status === "complete" && (!item.memberAffirmed || !provenance)) throw new Error("Unaffirmed complete coverage");
    return { status: item.status, memberAffirmed: item.memberAffirmed, source: provenance };
  };
  const coverage = { planned: lane("planned"), actual: lane("actual") };
  let opening: CashFlowPayload["opening"] = null;
  if (row.opening !== null) {
    const item = cashFlowObject(row.opening, ["amountToman", "atStartOn", "source"]), atStartOn = item.atStartOn === null ? null : cashFlowDay(item.atStartOn);
    if (atStartOn !== null && atStartOn !== period.startOn) throw new Error("Invalid opening date");
    opening = { amountToman: amount(item.amountToman, true), atStartOn, source: source(item.source) };
  }
  if (!Array.isArray(row.entries) || row.entries.length > 500) throw new Error("Invalid cash-flow entries");
  const entryKeys = new Set<string>();
  const entries: CashFlowPayload["entries"] = row.entries.map(value => {
    if (!value || typeof value !== "object") throw new Error("Invalid cash-flow entry");
    const kind = (value as Record<string, unknown>).kind;
    const item = cashFlowObject(value, ["entryKey", "basis", "kind", "amountToman", "occurredOn", "source", "category", "note", ...(kind === "transfer" ? ["fromAccountKey", "toAccountKey"] : ["accountKey"])]);
    if (kind !== "income" && kind !== "expense" && kind !== "transfer" || item.basis !== "planned" && item.basis !== "actual") throw new Error("Invalid cash-flow event kind");
    const entryKey = cashFlowText(item.entryKey, 200), occurredOn = item.occurredOn === null ? null : cashFlowDay(item.occurredOn);
    if (entryKeys.has(entryKey) || occurredOn !== null && (occurredOn < period.startOn || occurredOn > period.endOn)) throw new Error("Duplicate/outside cash-flow event");
    entryKeys.add(entryKey);
    const common = { entryKey, basis: item.basis, amountToman: amount(item.amountToman), occurredOn, source: source(item.source), category: nullableText(item.category, 160), note: nullableText(item.note, 2000) };
    if (coverage[item.basis].status === "complete" && (common.amountToman === null || occurredOn === null || common.source === null)) throw new Error("Unknown complete cash-flow event");
    if (kind === "transfer") {
      const fromAccountKey = cashFlowText(item.fromAccountKey, 200), toAccountKey = cashFlowText(item.toAccountKey, 200);
      if (fromAccountKey === toAccountKey || !keys.has(fromAccountKey) || !keys.has(toAccountKey)) throw new Error("Invalid transfer references");
      return { ...common, basis: item.basis, kind, fromAccountKey, toAccountKey };
    }
    const accountKey = cashFlowText(item.accountKey, 200);
    if (!keys.has(accountKey)) throw new Error("Invalid account reference");
    return { ...common, basis: item.basis, kind, accountKey };
  });
  return { contractVersion: 1, period, accountDefinitions, scopeAccountKeys, opening, coverage, entries };
}
export function validateCashFlowWriteRequest(value: unknown): CashFlowWriteRequest {
  const row = cashFlowObject(value, ["contractVersion", "expectedOwnerId", "clientToken", "baseVersion", "payload"]);
  if (row.contractVersion !== "cash-flow-request.v1" || !cashFlowUuid(row.expectedOwnerId) || !Number.isInteger(row.baseVersion) || (row.baseVersion as number) < 0 || (row.baseVersion as number) >= 2_147_483_647) throw new Error("Invalid cash-flow request");
  return { contractVersion: "cash-flow-request.v1", expectedOwnerId: row.expectedOwnerId, clientToken: cashFlowText(row.clientToken, 200), baseVersion: row.baseVersion as number, payload: validateCashFlowPayload(row.payload) };
}
export function cashFlowReport(payload: CashFlowPayload, ownerId: string): CashFlowReport {
  return buildCashFlow({ period: payload.period, scope: { ownerId, accountKeys: payload.scopeAccountKeys }, readState: "ready", opening: payload.opening, coverage: payload.coverage, entries: payload.entries.map(entry => ({ ...entry, ownerId })) });
}
export function validateCashFlowReceipt(value: unknown, request: CashFlowWriteRequest): CashFlowReceipt {
  const row = cashFlowObject(value, ["contractVersion", "ownerId", "versionId", "version", "entryCount", "reused", "canonicalContentHash"]);
  if (row.contractVersion !== "cash-flow-write.v1" || row.ownerId !== request.expectedOwnerId || !cashFlowUuid(row.versionId) || row.version !== request.baseVersion + 1 || row.entryCount !== request.payload.entries.length || typeof row.reused !== "boolean" || typeof row.canonicalContentHash !== "string" || !/^[a-f0-9]{64}$/.test(row.canonicalContentHash)) throw new Error("Invalid cash-flow receipt");
  return row as unknown as CashFlowReceipt;
}
const positiveVersion = (value: unknown): value is number => typeof value === "number" && Number.isInteger(value) && value > 0 && value <= 2_147_483_647;
function metadata(value: unknown): { id: string; version: number; createdAt: string } {
  const row = cashFlowObject(value, ["id", "version", "createdAt"]);
  if (!cashFlowUuid(row.id) || !positiveVersion(row.version) || typeof row.createdAt !== "string" || !/^\d{4}-\d\d-\d\dT/.test(row.createdAt) || !Number.isFinite(Date.parse(row.createdAt))) throw new Error("Invalid cash-flow metadata");
  return { id: row.id, version: row.version, createdAt: row.createdAt };
}
/** Validate independent read data; always rebuild the report with the one canonical calculator. */
export function validateCashFlowRead(value: unknown, expected: { period: CashFlowPeriod; version?: string; beforeVersion?: number; ownerId?: string }): CashFlowRead {
  const row = cashFlowObject(value, ["contractVersion", "state", "ownerId", "period", "snapshot", "report", "latest", "history"]);
  const period = validateCashFlowPeriod(row.period);
  if (row.contractVersion !== "cash-flow-read.v1" || !cashFlowUuid(row.ownerId) || expected.ownerId !== undefined && expected.ownerId !== row.ownerId || period.startOn !== expected.period.startOn || period.endOn !== expected.period.endOn) throw new Error("Invalid cash-flow read context");
  const latest = cashFlowObject(row.latest, ["state", "id", "version"]);
  if (latest.state === "error") { if (latest.id !== null || latest.version !== null) throw new Error("Invalid latest error"); }
  else if (latest.state !== "ready" || !(latest.version === 0 && latest.id === null || positiveVersion(latest.version) && cashFlowUuid(latest.id))) throw new Error("Invalid cash-flow latest");
  const history = cashFlowObject(row.history, ["state", "items", "nextBeforeVersion"]);
  if (!Array.isArray(history.items) || history.items.length > 20) throw new Error("Invalid cash-flow history");
  const items = history.items.map(metadata);
  if (history.state === "error") { if (items.length || history.nextBeforeVersion !== null) throw new Error("Invalid history error"); }
  else if (history.state !== "ready" || items.some((item, index) => index > 0 && item.version >= items[index - 1].version || expected.beforeVersion !== undefined && item.version >= expected.beforeVersion) || new Set(items.map(item => item.id)).size !== items.length || history.nextBeforeVersion !== null && (items.length !== 20 || history.nextBeforeVersion !== items.at(-1)?.version)) throw new Error("Invalid history cursor/order");
  if (latest.state === "ready" && items.some(item => item.version > (latest.version as number) || item.version === latest.version && item.id !== latest.id)) throw new Error("History/latest mismatch");
  let snapshot: CashFlowRead["snapshot"] = null, report: CashFlowReport | null = null;
  if (row.state === "empty") {
    if (expected.version || row.snapshot !== null || row.report !== null || latest.state !== "ready" || latest.version !== 0 || history.state !== "ready" || items.length || history.nextBeforeVersion !== null) throw new Error("Invalid cash-flow empty state");
  } else if (row.state === "ready") {
    const selected = cashFlowObject(row.snapshot, ["id", "version", "createdAt", "payload"]);
    const info = metadata({ id: selected.id, version: selected.version, createdAt: selected.createdAt }), payload = validateCashFlowPayload(selected.payload);
    if (expected.version !== undefined && info.id !== expected.version || payload.period.startOn !== period.startOn || payload.period.endOn !== period.endOn || latest.state === "ready" && ((latest.version as number) < info.version || latest.version === info.version && latest.id !== info.id) || expected.version === undefined && (latest.state !== "ready" || latest.id !== info.id || latest.version !== info.version)) throw new Error("Invalid selected cash-flow version");
    snapshot = { ...info, payload }; report = cashFlowReport(payload, row.ownerId);
    if (items.some(item => item.version === info.version && item.id !== info.id)) throw new Error("History/selected mismatch");
    if (stableJson(row.report) !== stableJson(report)) throw new Error("Invalid cash-flow report");
  } else throw new Error("Invalid cash-flow state");
  return { contractVersion: "cash-flow-read.v1", state: row.state, ownerId: row.ownerId, period, snapshot, report,
    latest: latest as unknown as CashFlowRead["latest"], history: { state: history.state as "ready" | "error", items, nextBeforeVersion: history.nextBeforeVersion as number | null } };
}
function stableJson(value: unknown): string {
  return JSON.stringify(value, (_, item) => item !== null && typeof item === "object" && !Array.isArray(item) ? Object.fromEntries(Object.keys(item).sort().map(key => [key, item[key]])) : item);
}
export function validateCashFlowError(value: unknown, status: number): CashFlowApiError | null {
  const codes: Record<number, readonly CashFlowErrorCode[]> = { 400: ["INVALID_INPUT"], 401: ["AUTH_REQUIRED"], 403: ["FORBIDDEN", "OWNER_CHANGED", "ORIGIN_FORBIDDEN"], 404: ["NOT_FOUND"], 409: ["CONFLICT"], 413: ["BODY_TOO_LARGE"], 429: ["RATE_LIMITED"], 503: ["AUTH_UNAVAILABLE", "READ_UNAVAILABLE", "WRITE_UNAVAILABLE"] };
  try {
    const row = cashFlowObject(value, ["state", "code", "error"]);
    if (row.state !== "error" || typeof row.code !== "string" || !codes[status]?.includes(row.code as CashFlowErrorCode) || typeof row.error !== "string" || !row.error.trim() || row.error.length > 500) return null;
    return row as unknown as CashFlowApiError;
  } catch { return null; }
}

import { dateInput, moneyInput, type Currency } from "./financialInput";

export type CashFlowBasis = "planned" | "actual";
export interface CashFlowSource { label: string; observedOn: string }
export interface CashFlowPeriod { startOn: string; endOn: string }
export interface CashFlowScope { ownerId: string; accountKeys: readonly string[] }
interface EntryBase {
  entryKey: string; ownerId: string; basis: CashFlowBasis;
  occurredOn: string | null; amountToman: number | null; source: CashFlowSource | null;
  category: string | null; note: string | null;
}
/** One transfer event, not two expense/income legs. Account keys are cash-scope references, not assets. */
export type CashFlowEntry = EntryBase & (
  { kind: "income" | "expense"; accountKey: string }
  | { kind: "transfer"; fromAccountKey: string; toAccountKey: string }
);
export interface CashFlowCoverage {
  status: "unknown" | "partial" | "complete";
  /** Complete is an explicit assertion covering this entire owner/account scope and period. */
  source: CashFlowSource | null;
}
export interface CashFlowInput {
  period: CashFlowPeriod; scope: CashFlowScope; readState: "ready" | "unavailable";
  entries: readonly CashFlowEntry[];
  coverage: Record<CashFlowBasis, CashFlowCoverage>;
  /** Balance at the START of startOn, not a transaction and not automatically zero. */
  opening: { amountToman: number | null; atStartOn: string | null; source: CashFlowSource | null } | null;
}
export type CashFlowIssue = "invalid_period" | "invalid_scope" | "read_unavailable" | "coverage_unknown"
  | "coverage_partial" | "coverage_source_missing" | "entry_key_invalid" | "duplicate_entry"
  | "entry_date_invalid" | "entry_account_invalid" | "entry_amount_invalid" | "entry_source_missing" | "transfer_invalid" | "unsafe_total";
export interface CashFlowLane {
  state: "complete" | "partial" | "unknown" | "unavailable" | "invalid";
  /** Known records only; null means no known contribution, not zero activity. */
  incomeKnown: number | null; expenseKnown: number | null;
  transferInKnown: number | null; transferOutKnown: number | null;
  knownNet: number | null;
  /** Definitive only with explicit complete coverage and valid, sourced records. */
  netToman: number | null; closingToman: number | null;
  closingState: "known" | "opening_unknown" | "opening_invalid" | "flow_partial" | "unsafe";
  includedEntries: number; internalTransfers: number; issues: CashFlowIssue[];
}
export interface CashFlowReport {
  contractVersion: 1; period: CashFlowPeriod | null; planned: CashFlowLane; actual: CashFlowLane;
  opening: { state: "known" | "unknown" | "invalid"; amountToman: number | null };
  actualMinusPlanned: number | null;
}

/** Reuse the existing single IRR→IRT boundary; unknown is allowed only explicitly. */
export function cashFlowAmount(value: unknown, currency: Currency): number | null {
  return value === null ? null : moneyInput(value, currency);
}
function day(value: unknown): string | null {
  if (typeof value !== "string") return null;
  try { return dateInput(value); } catch { return null; }
}
const text = (value: unknown): value is string => typeof value === "string" && value.trim().length > 0;
function sourced(value: CashFlowSource | null): boolean {
  return value !== null && text(value.label) && !["unknown", "نامشخص", "-", "—"].includes(value.label.trim().toLowerCase()) && day(value.observedOn) !== null;
}
const safeLimit = BigInt(Number.MAX_SAFE_INTEGER);
function exact(value: bigint): number | null { return value <= safeLimit && value >= -safeLimit ? Number(value) : null; }
function blank(state: CashFlowLane["state"], issue: CashFlowIssue): CashFlowLane {
  return { state, incomeKnown: null, expenseKnown: null, transferInKnown: null, transferOutKnown: null,
    knownNet: null, netToman: null, closingToman: null, closingState: "flow_partial", includedEntries: 0, internalTransfers: 0, issues: [issue] };
}

/** Pure dated cash-flow calculation; this is neither persistence nor an authorization boundary. */
export function buildCashFlow(input: CashFlowInput): CashFlowReport {
  const startOn = day(input.period.startOn), endOn = day(input.period.endOn);
  const period = startOn && endOn && startOn <= endOn ? { startOn, endOn } : null;
  const scopeValid = text(input.scope.ownerId) && input.scope.accountKeys.length > 0
    && input.scope.accountKeys.every(text) && new Set(input.scope.accountKeys).size === input.scope.accountKeys.length;
  const blocked = !period ? "invalid_period" : !scopeValid ? "invalid_scope" : input.readState !== "ready" ? "read_unavailable" : null;
  if (blocked) return { contractVersion: 1, period, planned: blank(blocked === "read_unavailable" ? "unavailable" : "invalid", blocked),
    actual: blank(blocked === "read_unavailable" ? "unavailable" : "invalid", blocked), opening: { state: "unknown", amountToman: null }, actualMinusPlanned: null };
  // The guard above establishes a valid period. No dates are converted to instants.
  const selectedPeriod = period!;
  const owned = input.entries.filter(entry => entry.ownerId === input.scope.ownerId);
  const accountKeys = new Set(input.scope.accountKeys);
  const keyCounts = new Map<string, number>();
  for (const entry of owned) keyCounts.set(entry.entryKey, (keyCounts.get(entry.entryKey) ?? 0) + 1);
  const opening = input.opening;
  const openingKnown = opening !== null && Number.isSafeInteger(opening.amountToman)
    && day(opening.atStartOn) === selectedPeriod.startOn && sourced(opening.source);
  const openingState: CashFlowReport["opening"] = opening === null || opening.amountToman === null
    ? { state: "unknown", amountToman: null }
    : openingKnown ? { state: "known", amountToman: opening.amountToman } : { state: "invalid", amountToman: null };

  function lane(basis: CashFlowBasis): CashFlowLane {
    const coverage = input.coverage[basis], issues = new Set<CashFlowIssue>();
    if (coverage.status === "unknown") issues.add("coverage_unknown");
    if (coverage.status === "partial") issues.add("coverage_partial");
    if (coverage.status === "complete" && !sourced(coverage.source)) issues.add("coverage_source_missing");
    const totals = { income: BigInt(0), expense: BigInt(0), transferIn: BigInt(0), transferOut: BigInt(0) };
    const seen = { income: false, expense: false, transferIn: false, transferOut: false };
    let includedEntries = 0, internalTransfers = 0, knownContributions = 0;
    for (const entry of owned) {
      if (entry.basis !== basis) continue;
      const occurredOn = day(entry.occurredOn);
      if (occurredOn && (occurredOn < selectedPeriod.startOn || occurredOn > selectedPeriod.endOn)) continue;
      let bucket: keyof typeof totals | "internal";
      if (entry.kind === "transfer") {
        if (!text(entry.fromAccountKey) || !text(entry.toAccountKey)) { issues.add("transfer_invalid"); continue; }
        const from = accountKeys.has(entry.fromAccountKey), to = accountKeys.has(entry.toAccountKey);
        if (!from && !to) continue;
        if (entry.fromAccountKey === entry.toAccountKey) {
          issues.add("transfer_invalid"); continue;
        }
        bucket = from && to ? "internal" : to ? "transferIn" : "transferOut";
      } else {
        if (!text(entry.accountKey)) { issues.add("entry_account_invalid"); continue; }
        if (!accountKeys.has(entry.accountKey)) continue;
        bucket = entry.kind;
      }
      if (!occurredOn) { issues.add("entry_date_invalid"); continue; }
      if (!text(entry.entryKey)) { issues.add("entry_key_invalid"); continue; }
      if ((keyCounts.get(entry.entryKey) ?? 0) > 1) { issues.add("duplicate_entry"); continue; }
      includedEntries++;
      if (!sourced(entry.source)) issues.add("entry_source_missing");
      const amountKnown = typeof entry.amountToman === "number" && Number.isSafeInteger(entry.amountToman) && entry.amountToman >= 0;
      if (!amountKnown) issues.add("entry_amount_invalid");
      if (bucket === "internal") { internalTransfers++; knownContributions++; continue; }
      if (!amountKnown) continue;
      totals[bucket] += BigInt(entry.amountToman!); seen[bucket] = true; knownContributions++;
    }
    const net = exact(totals.income - totals.expense + totals.transferIn - totals.transferOut);
    if (Object.values(totals).some(value => exact(value) === null) || net === null) issues.add("unsafe_total");
    const complete = coverage.status === "complete" && issues.size === 0;
    const state = complete ? "complete" : coverage.status === "unknown" && includedEntries === 0 && issues.size === 1 ? "unknown" : "partial";
    const closing = complete && net !== null && openingState.state === "known" ? exact(BigInt(openingState.amountToman!) + BigInt(net)) : null;
    return { state, incomeKnown: seen.income || complete ? exact(totals.income) : null,
      expenseKnown: seen.expense || complete ? exact(totals.expense) : null,
      transferInKnown: seen.transferIn || complete ? exact(totals.transferIn) : null,
      transferOutKnown: seen.transferOut || complete ? exact(totals.transferOut) : null,
      knownNet: knownContributions > 0 || complete ? net : null, netToman: complete ? net : null,
      closingToman: closing, closingState: !complete ? "flow_partial" : openingState.state === "unknown" ? "opening_unknown"
        : openingState.state === "invalid" ? "opening_invalid" : closing === null ? "unsafe" : "known",
      includedEntries, internalTransfers, issues: [...issues] };
  }
  const planned = lane("planned"), actual = lane("actual");
  return { contractVersion: 1, period: selectedPeriod, planned, actual, opening: openingState,
    actualMinusPlanned: planned.netToman !== null && actual.netToman !== null ? exact(BigInt(actual.netToman) - BigInt(planned.netToman)) : null };
}

import { toLatinDigits } from "../format";
export type Currency = "IRR" | "IRT";
export type DebtKind = "loan" | "personal" | "installment";
export const DEBT_LABELS: Record<DebtKind, string> = { loan: "وام", personal: "قرض شخصی", installment: "بدهی اقساطی" };
export function text(value: unknown): string { return typeof value === "string" ? value.trim() : ""; }
export function numberInput(value: unknown): number {
  if (typeof value === "number") return value;
  const raw = toLatinDigits(text(value)).replace(/٫/g, ".");
  // Validate grouping before removing it: "12,34" must never become 1234.
  // A comma is a thousands separator here, never an inferred decimal mark.
  const plain = /^\d+(?:\.\d+)?$/;
  const grouped = /^\d{1,3}([,٬])\d{3}(?:\1\d{3})*(?:\.\d+)?$/;
  return plain.test(raw) || grouped.test(raw) ? Number(raw.replace(/[,٬]/g, "")) : NaN;
}
export function dateInput(value: unknown): string {
  const date = toLatinDigits(text(value));
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(Date.parse(date)) || new Date(date).toISOString().slice(0, 10) !== date) throw new Error("تاریخ معتبر را به شکل YYYY-MM-DD وارد کنید.");
  return date;
}
export function moneyInput(value: unknown, currency: unknown): number {
  if (currency !== "IRR" && currency !== "IRT") throw new Error("واحد پول باید ریال یا تومان باشد.");
  // Reject a nonzero textual fraction before Number can round it to an integer.
  const fraction = toLatinDigits(text(value)).split(/[.٫]/)[1];
  if (fraction && /[1-9]/.test(fraction)) throw new Error("مبلغ باید عدد صحیح نامنفی و در محدودهٔ قابل محاسبه باشد.");
  const n = numberInput(value);
  if (!Number.isSafeInteger(n) || n < 0) throw new Error("مبلغ باید عدد صحیح نامنفی و در محدودهٔ قابل محاسبه باشد.");
  const toman = currency === "IRR" ? n / 10 : n;
  if (!Number.isSafeInteger(toman)) throw new Error("مبلغ ریالی باید مضرب ۱۰ باشد؛ ذخیره به تومان صحیح انجام می‌شود.");
  return toman;
}
export function normalisePosition(input: unknown): Record<string, unknown> {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("قلم دارایی نامعتبر است.");
  const r = input as Record<string, unknown>;
  const symbol = text(r.symbol), label = text(r.manual_label);
  if (!text(r.position_key) || !text(r.asset_class) || !text(r.unit) || !!symbol === !!label) throw new Error("شناسه، دسته، واحد و دقیقاً یک نماد یا عنوان دستی لازم است.");
  const ownership = r.ownership_pct === undefined ? 100 : numberInput(r.ownership_pct);
  if (!Number.isFinite(ownership) || ownership <= 0 || ownership > 100 || Math.abs(ownership * 100 - Math.round(ownership * 100)) > 1e-8) throw new Error("سهم مالکیت باید بیشتر از صفر تا ۱۰۰ درصد با حداکثر دو رقم اعشار باشد.");
  const mode = r.valuation_mode ?? "market";
  if (!["market", "declared", "unpriced"].includes(String(mode))) throw new Error("روش ارزش‌گذاری نامعتبر است.");
  const qty = r.qty === null || r.qty === undefined || text(r.qty) === "" && typeof r.qty !== "number" ? null : numberInput(r.qty);
  if ((qty === null && mode !== "declared") || qty !== null && (!Number.isFinite(qty) || qty <= 0 || qty > Number.MAX_SAFE_INTEGER)) throw new Error("مقدار مثبت یا ارزش اظهارشده لازم است.");
  const out: Record<string, unknown> = { position_key: text(r.position_key), symbol: symbol || null, manual_label: label || null, asset_class: text(r.asset_class), qty, unit: text(r.unit), as_of: dateInput(r.as_of), title: text(r.title) || null, ownership_pct: ownership, valuation_mode: mode, declared_value: null, valuation_source: null, valuation_as_of: null, valuation_status: mode === "unpriced" ? "missing" : "valid" };
  if (mode === "declared") {
    if (!["valid", "estimated"].includes(String(r.valuation_status)) || !text(r.valuation_source) || ["unknown", "نامشخص", "-", "—"].includes(text(r.valuation_source).toLowerCase())) throw new Error("منبع و وضعیت معتبر یا تخمینی ارزش‌گذاری لازم است.");
    out.declared_value = moneyInput(r.declared_value, r.currency);
    out.valuation_source = text(r.valuation_source);
    out.valuation_as_of = dateInput(r.valuation_as_of);
    out.valuation_status = r.valuation_status;
  }
  if (r.cost_basis !== undefined && r.cost_basis !== null && r.cost_basis !== "") out.cost_basis = moneyInput(r.cost_basis, "IRT");
  return out;
}
export function normaliseDebt(input: unknown): Record<string, unknown> {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw new Error("بدهی نامعتبر است.");
  const r = input as Record<string, unknown>;
  if (!text(r.debt_key) || !text(r.title) || text(r.title).length > 300 || !Object.hasOwn(DEBT_LABELS, String(r.kind))) throw new Error("عنوان و نوع بدهی لازم است؛ ضمانت و تعهد احتمالی در این بخش ثبت نمی‌شوند.");
  const hasPayment = r.next_installment !== null && r.next_installment !== undefined && r.next_installment !== "";
  if (hasPayment !== !!text(r.next_due_on)) throw new Error("مبلغ و موعد قسط بعدی باید با هم وارد شوند.");
  if (text(r.note).length > 2000) throw new Error("توضیح بدهی حداکثر ۲۰۰۰ نویسه است.");
  return { debt_key: text(r.debt_key), title: text(r.title), kind: r.kind, balance_toman: moneyInput(r.balance, r.currency), currency: r.currency, balance_as_of: dateInput(r.balance_as_of), next_installment_toman: hasPayment ? moneyInput(r.next_installment, r.currency) : null, next_due_on: hasPayment ? dateInput(r.next_due_on) : null, note: text(r.note) || null };
}

// Persian / Iranian financial formatting — pure, dependency-free, deterministic.
// Safe to import in both server and client components. Money is handled as
// integer Toman. Dates use the Persian (Jalali) calendar via Intl so the output
// is the same on server and client (no hydration mismatch).

const FA_DIGITS = ["۰", "۱", "۲", "۳", "۴", "۵", "۶", "۷", "۸", "۹"];

/** Convert all Latin digits in a string/number to Persian digits. */
export function toPersianDigits(input: string | number): string {
  return String(input).replace(/\d/g, (d) => FA_DIGITS[Number(d)]);
}

const FA_AR_DIGITS = /[۰-۹٠-٩]/g;
const TO_LATIN: Record<string, string> = {
  "۰": "0", "۱": "1", "۲": "2", "۳": "3", "۴": "4", "۵": "5", "۶": "6", "۷": "7", "۸": "8", "۹": "9",
  "٠": "0", "١": "1", "٢": "2", "٣": "3", "٤": "4", "٥": "5", "٦": "6", "٧": "7", "٨": "8", "٩": "9",
};

/** Convert Persian/Arabic digits to Latin — use before parsing or validating user input. */
export function toLatinDigits(input: string): string {
  return input.replace(FA_AR_DIGITS, (d) => TO_LATIN[d] ?? d);
}

function groupThousands(n: number): string {
  return Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, "٬");
}

/** Full Toman amount, e.g. 1250000 → "۱٬۲۵۰٬۰۰۰ تومان". */
export function formatToman(value: number): string {
  return `${toPersianDigits(groupThousands(value))} تومان`;
}

/**
 * Abbreviated Toman, e.g. 3_500_000_000 → "۳٫۵ میلیارد تومان".
 *
 * ── چرا پلهٔ «همت» اضافه شد ───────────────────────────────────────────────
 * بالاترین پلهٔ قبلی «میلیارد» بود، پس جمع‌های سطحِ بازار — ارزشِ معاملاتِ کل و
 * خالصِ پولِ حقیقی — به شکلِ «۳۳۲٬۹۲۸٬۱۴۶٫۲ میلیارد تومان» درمی‌آمدند: عددی که
 * نه خوانده می‌شود، نه در کارتِ سنجه جا می‌شود. «همت» (هزار میلیارد تومان)
 * واحدِ متعارفِ همین بازار است و در `TodayDashboard` هم به‌صورتِ محلی ساخته
 * شده بود؛ حالا یک بار اینجاست و همه از همین می‌خوانند.
 */
export function formatTomanShort(value: number): string {
  const abs = Math.abs(value);
  let num = value;
  let unit = "";
  if (abs >= 1_000_000_000_000) {
    num = value / 1_000_000_000_000;
    unit = " همت";
  } else if (abs >= 1_000_000_000) {
    num = value / 1_000_000_000;
    unit = " میلیارد";
  } else if (abs >= 1_000_000) {
    num = value / 1_000_000;
    unit = " میلیون";
  } else if (abs >= 1_000) {
    num = value / 1_000;
    unit = " هزار";
  }
  // علامتِ منفی: همان «−» (U+2212) که `formatPercent` می‌گذارد، نه خطِ تیرهٔ
  // اسکی. دو علامتِ متفاوت برای یک معنا در یک صفحه، و در RTL خطِ تیرهٔ اسکی
  // کنارِ رقمِ فارسی جهتش مبهم می‌شود.
  const sign = num < 0 ? "−" : "";
  const mag = Math.abs(num);
  const body = unit ? mag.toFixed(mag % 1 === 0 ? 0 : 1) : groupThousands(mag);
  // «همت» خودش مخفّفِ «هزار میلیارد تومان» است، پس «۴۱۵٫۴ همت تومان» یعنی
  // «…تومان تومان». واحد یک بار نوشته می‌شود؛ بقیهٔ پله‌ها («میلیارد»،
  // «میلیون»، …) عدد خالص‌اند و «تومان» را لازم دارند.
  const currency = unit === " همت" ? "" : " تومان";
  return `${sign}${toPersianDigits(body).replace(".", "٫")}${unit}${currency}`;
}

/** Percent with Persian decimal/sign, e.g. 12.5 → "٪۱۲٫۵", -3.2 → "−٪۳٫۲". */
export function formatPercent(value: number, digits = 1): string {
  const sign = value < 0 ? "−" : "";
  const body = toPersianDigits(Math.abs(value).toFixed(digits)).replace(".", "٫");
  return `${sign}٪${body}`;
}

/** Signed change with arrow, e.g. 2.4 → "▲ ٪۲٫۴". */
export function formatSignedPercent(value: number, digits = 1): string {
  const arrow = value > 0 ? "▲" : value < 0 ? "▼" : "•";
  return `${arrow} ${formatPercent(Math.abs(value), digits)}`;
}

/** Screen-reader phrasing for a delta, e.g. "افزایش ۲٫۴ درصدی". */
export function describeDelta(value: number): string {
  if (value > 0) return `افزایش ${toPersianDigits(Math.abs(value).toFixed(1))} درصدی`;
  if (value < 0) return `کاهش ${toPersianDigits(Math.abs(value).toFixed(1))} درصدی`;
  return "بدون تغییر";
}

/** Dollar price with Persian digits, e.g. 67250.3 → "۶۷٬۲۵۰ دلار"; sub-1 keeps 3 significant digits. */
export function formatUsd(value: number): string {
  const s = value >= 1 ? Math.round(value).toLocaleString("en-US") : value.toPrecision(3);
  return `${toPersianDigits(s).replace(/,/g, "٬").replace(".", "٫")} دلار`;
}

/** CSS-variable color for a financial delta (matches the project's tokens). */
export function deltaColor(value: number): string {
  if (value > 0) return "var(--success)";
  if (value < 0) return "var(--danger)";
  return "var(--text-3)";
}

const FA_MONTHS = [
  "فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
  "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند",
];

const jalaliParts = new Intl.DateTimeFormat("en-US-u-ca-persian", {
  timeZone: "Asia/Tehran",
  year: "numeric",
  month: "numeric",
  day: "numeric",
});

/** Jalali date. long=true (default) → "۱ فروردین ۱۴۰۴", false → "۱۴۰۴/۰۱/۰۱". */
export function formatJalali(date: string | number | Date, long = true): string {
  const d = typeof date === "string" || typeof date === "number" ? new Date(date) : date;
  const parts = jalaliParts.formatToParts(d);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  const y = Number(get("year"));
  const m = Number(get("month"));
  const day = Number(get("day"));
  if (long) {
    return `${toPersianDigits(day)} ${FA_MONTHS[m - 1]} ${toPersianDigits(y)}`;
  }
  const mm = String(m).padStart(2, "0");
  const dd = String(day).padStart(2, "0");
  return toPersianDigits(`${y}/${mm}/${dd}`);
}

/** Short Jalali for chart axes, e.g. "۱ فروردین". */
export function formatJalaliShort(date: string | number | Date): string {
  const d = typeof date === "string" || typeof date === "number" ? new Date(date) : date;
  const parts = jalaliParts.formatToParts(d);
  const get = (t: string) => parts.find((p) => p.type === t)?.value ?? "";
  return `${toPersianDigits(Number(get("day")))} ${FA_MONTHS[Number(get("month")) - 1]}`;
}

/* ── تفکیک‌هایی که نبودشان باگِ عددی می‌سازد ─────────────────────────────── */

/**
 * **واحدِ درصد** (percentage point) — نه درصد.
 *
 * ── چرا تابعِ جداست ──────────────────────────────────────────────────────
 * «حبابِ این صندوق ۲ واحدِ درصد از میانه بالاتر است» و «حباب ۲٪ بالاتر است»
 * دو گزارهٔ متفاوت‌اند و با هم اشتباه گرفتن‌شان عددِ خروجی را عوض می‌کند.
 * وقتی هر دو با `formatPercent` نوشته شوند، هیچ‌کس در UI نمی‌تواند تشخیص
 * بدهد کدام است. این تابع تفاوت را **در خودِ متن** می‌گذارد.
 */
export function formatPercentPoints(value: number, digits = 1): string {
  const sign = value < 0 ? "−" : "";
  const body = toPersianDigits(Math.abs(value).toFixed(digits)).replace(".", "٫");
  return `${sign}${body} واحدِ درصد`;
}

